class Solution:
    def findPrefixScore(self, nums: list[int]) -> list[int]:
        max_val = 0
        total_score = 0
        ans = []
        for x in nums:
            max_val = max(max_val, x)
            total_score += x + max_val
            ans.append(total_score)
        return ans

class Solution {
public:
    std::vector<long long> findPrefixScore(std::vector<int>& nums) {
        long long max_val = 0;
        long long total = 0;
        std::vector<long long> ans;
        ans.reserve(nums.size());
        for (int x : nums) {
            max_val = std::max(max_val, (long long)x);
            total += (long long)x + max_val;
            ans.push_back(total);
        }
        return ans;
    }
};

class Solution {
    public long[] findPrefixScore(int[] nums) {
        int n = nums.length;
        long[] ans = new long[n];
        long maxVal = 0;
        long total = 0;
        for (int i = 0; i < n; i++) {
            maxVal = Math.max(maxVal, nums[i]);
            total += (long) nums[i] + maxVal;
            ans[i] = total;
        }
        return ans;
    }
}

